def format_event(event_type, *details, **fields):
    parts = [event_type.upper()]
    if details:
        parts.append(" ".join(str(detail) for detail in details))
    if fields:
        parts.append(" ".join(f"{key}={fields[key]}" for key in sorted(fields)))
    return " | ".join(parts)


def make_limiter(max_calls):
    calls = 0

    def allow():
        nonlocal calls
        calls += 1
        return calls <= max_calls

    return allow

