from contextlib import contextmanager
from functools import wraps


def audit(log):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                result = func(*args, **kwargs)
            except Exception:
                log.append((func.__name__, "error"))
                raise
            log.append((func.__name__, "ok"))
            return result
        return wrapper
    return decorator


@contextmanager
def temporary_flag(settings, key, value):
    existed = key in settings
    previous = settings.get(key)
    settings[key] = value
    try:
        yield
    finally:
        if existed:
            settings[key] = previous
        else:
            del settings[key]

