ALLOWED_PORTS = {443, 8443}


def check_url(url):
    try:
        parts = urlparse(url)
        port = parts.port
    except ValueError:
        return False
    if parts.scheme != "https" or not parts.hostname:
        return False
    if parts.username or parts.password:
        return False
    if port is not None and port not in ALLOWED_PORTS:
        return False
    try:
        address = ip_address(parts.hostname)
    except ValueError:
        return True  # a normal host name (a real system must also check what it resolves to)
    return address.is_global

