import hashlib

GENESIS = "0" * 64


def link(previous_hash, text):
    return hashlib.sha256((previous_hash + text).encode()).hexdigest()


class AuditLog:
    def __init__(self):
        self.entries = []

    @property
    def head(self):
        return self.entries[-1][1] if self.entries else GENESIS

    def append(self, text):
        self.entries.append((text, link(self.head, text)))

    def verify(self):
        previous = GENESIS
        for text, digest in self.entries:
            if link(previous, text) != digest:
                return False
            previous = digest
        return True

