import hashlib


class Toolkit:
    def __init__(self):
        self.log = []

    def check_password(self, password):
        strong = (
            len(password) >= 10
            and any(char.isdigit() for char in password)
            and any(char.isupper() for char in password)
        )
        result = "strong" if strong else "weak"
        self.log.append(f"checked password: {result}")
        return result

    def hash_text(self, text):
        digest = hashlib.sha256(text.encode()).hexdigest()
        self.log.append("hashed text")
        return digest

    def history(self):
        return list(self.log)


def main():
    toolkit = Toolkit()
    while True:
        line = input()
        command, _, rest = line.partition(" ")
        if command == "quit":
            print("Goodbye!")
            break
        elif command == "password":
            print(toolkit.check_password(rest))
        elif command == "hash":
            print(toolkit.hash_text(rest))
        elif command == "history":
            print(", ".join(toolkit.history()))
        else:
            print(f"Unknown command: {command}")


main()
